class Solution {
public:
    int countAsterisks(string s) {
        int ans = 0, i = 0;
        stringstream ss(s); string tok;
        while (getline(ss, tok, '|')) {
            if (i % 2 == 0) ans += count(tok.begin(), tok.end(), '*');
            i++;
        }
        return ans;
    }
};

