class Solution {
    public int countAsterisks(String s) {
        int ans = 0;
        String[] parts = s.split("\\|");
        for (int i = 0; i < parts.length; i += 2)
            for (char c : parts[i].toCharArray())
                if (c == '*') ans++;
        return ans;
    }
}

